SELECT MAX(STEPS) MAX_V, MIN(STEPS) MIN_V, ROUND(AVG(STEPS)) AVG_V
  FROM STEP_DAILY
 WHERE STAT_DATE = #{statDate}

SELECT COUNT(DISTINCT NVL(CARD_CODE, 'imei:' || DEVICE_IMEI))
  FROM ALERT_EVENT
 WHERE CATEGORY = #{category} AND OCCURRED_AT >= #{dayStart} AND OCCURRED_AT < #{dayEnd}

SELECT COUNT(*)
  FROM ALERT_EVENT
 WHERE SRC = 'DEVICE' AND CATEGORY = 'OTHER' AND OCCURRED_AT >= #{dayStart} AND OCCURRED_AT < #{dayEnd}
